import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]
    left = [0]*n
    right = [0]*n
    # left[i] = count of consecutive '1's ending at i-1
    for i in range(1, n):
        if s[i-1] == '1':
            left[i] = left[i-1] + 1
    # right[i] = count of consecutive '2's starting at i+1
    for i in range(n-2, -1, -1):
        if s[i+1] == '2':
            right[i] = right[i+1] + 1
    ans = 0
    for i, ch in enumerate(s):
        if ch == '/':
            l = left[i]
            r = right[i]
            length = l + 1 + r
            if (l + r) % 2 == 1:
                # reduce one side if possible
                if l > 0 or r > 0:
                    length -= 1
            if length > ans:
                ans = length
    print(ans)

if __name__ == "__main__":
    main()
